export function makeSample(AMx) {
  const W = 1280, H = 960, c = document.createElement('canvas'); c.width = W; c.height = H; const x = c.getContext('2d');
  const poly = (pts, fill) => { x.beginPath(); pts.forEach((p, i) => i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1])); x.closePath(); x.fillStyle = fill; x.fill(); };
  const rot = (cx, cy, side, deg) => { const r = side / Math.SQRT2, a = deg * Math.PI / 180; return [-135, -45, 45, 135].map(d => { const t = d * Math.PI / 180 + a; return [cx + Math.cos(t) * r, cy + Math.sin(t) * r]; }); };
  x.fillStyle = '#1e1e20'; x.fillRect(0, 0, W, H);
  const FRAME = [[180, 140], [1120, 170], [1090, 840], [210, 800]];
  poly(FRAME, '#5c5a57');
  const S = [
    [[260, 220], [560, 240], [550, 560], [250, 540]],
    [[640, 230], [1040, 260], [1030, 660], [650, 640]],
    [[300, 620], [480, 625], [478, 760], [298, 755]],
    rot(870, 760, 100, 20),
  ];
  ['#c9c6c0', '#d2cfc9', '#bdb9b2', '#cfcbc4'].forEach((f, i) => poly(S[i], f));
  // uma moldura escura fina à esquerda, para a foto não ser só blocos
  poly([[60, 60], [150, 62], [150, 900], [60, 900]], '#141416');
  // o que o projetor mostra na hora da foto, por cima de tudo: malha fina (32×18) em perspectiva e borda clara
  const Hm = AMx.homography(FRAME), P = (u, v) => AMx.apply(Hm, u, v);
  x.save(); x.beginPath(); FRAME.forEach((p, i) => i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1])); x.closePath(); x.clip();
  x.strokeStyle = 'rgba(0,0,0,.35)'; x.lineWidth = 2; x.beginPath();
  for (let i = 0; i <= 32; i++) { const a = P(i / 32, 0), b = P(i / 32, 1); x.moveTo(a[0], a[1]); x.lineTo(b[0], b[1]); }
  for (let j = 0; j <= 18; j++) { const a = P(0, j / 18), b = P(1, j / 18); x.moveTo(a[0], a[1]); x.lineTo(b[0], b[1]); }
  x.stroke();
  x.strokeStyle = '#ececec'; x.lineWidth = 20; x.beginPath(); FRAME.forEach((p, i) => i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1])); x.closePath(); x.stroke();
  x.restore();
  const id = x.getImageData(0, 0, W, H), d = id.data; let seed = 7;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  for (let i = 0; i < d.length; i += 4) { const n = (rnd() - 0.5) * 14; d[i] += n; d[i + 1] += n; d[i + 2] += n; }
  x.putImageData(id, 0, 0);
  return { canvas: c, frame: FRAME, truth: S };
}

